; SPF groups and SPA sequences for NHL 95 on the SNES.
; Generated by tools/build-snes95-frames.js from the NHL95SNES source: src/frames95s.asm for the SPF groups and the
; SPA*.asm lists of src/data/tables, in the order the ROM holds them. Frame numbers are the game's own (an index of
; FrameTileSource / FrameBankLayout, 1060 frames); a sequence is eight direction pointers, a flags word, then
; (frame, time) pairs ending in a negative time.

SPFskate     = 1	; 64 frames: skating: 8 slots a direction, 5 of them drawn (SPAskate)
SPFglide     = 65	; 8 frames: gliding, one a direction (SPAglide)
SPFstop      = 73	; 16 frames: stopping, 2 a direction (SPAstop)
SPFpad       = 111	; 1 frame: the controller stars (setupice, RestoreGameScreen)
SPFreplay    = 114	; 1 frame: the replay camera cursor, four corner marks (RestoreGameScreen;
SPFshoulderl = 123	; 8 frames: shoulder check left, one a direction (SPAshoulderchkl)
SPFshoulderr = 131	; 8 frames: shoulder check right, one a direction (SPAshoulderchkr)
SPFhook      = 139	; 16 frames: hooking (SPAhook, SPAhook2)
SPFHold      = 155	; 8 frames: holding, one a direction (SPAHold, SPAHold2)
SPFsweep     = 163	; 16 frames: sweep check (SPAsweepchk); SPAfaceoff uses +0, +1, +8 and +9
SPFfallfwd   = 179	; 48 frames: falling forward (SPAfallfwd; the board checks use some)
SPFfallback  = 227	; 40 frames: falling back (SPAfallback; SPAflip and the board checks use
SPFburst     = 267	; 64 frames: a speed burst: 8 slots a direction, 4 of them drawn
SPFskatewp   = 331	; 64 frames: skating with the puck: 8 slots a direction, 5 of them drawn
SPFpuck      = 435	; 11 frames: +0 the puck shadow, +1 to +10 the flipping puck (SPApflip;
SPFgoal      = 446	; 2 frames: the two nets (setupice, RestoreGameScreen)
SPFswing     = 448	; 48 frames: shot and pass swings, 6 a direction (SPAshotf, SPApassf,
SPFskateb    = 496	; 48 frames: skating backwards, 6 a direction (SPAskateback, SPAglideback)
SPFstumble   = 544	; 32 frames: stumbling, 4 a direction (SPAstumble)
SPFswingb    = 576	; 24 frames: the backhand pass and shot, 3 a direction (SPApassb,
SPFflip      = 600	; 6 frames: flipping over (SPAflip)
SPFGoalie    = 606	; 40 frames: the goalie, 5 runs of 8 (one a direction): +0 SPAgready2, +8
SPFgdive     = 646	; 24 frames: the goalie diving: 3 slots a direction, 2 of them drawn
SPFPen       = 670	; 7 frames: a player jumping over the boards into the box or onto the
SPFSiren     = 701	; 14 frames: the goal light (SPAsiren)
SPFgstack    = 715	; 40 frames: the goalie: +0 stacking left, +12 stacking right, +24 the
SPFcrosscheck= 810	; 8 frames: cross check, one a direction (SPAcrosscheck)
SPFcatch     = 818	; 16 frames: catching a pass, 2 a direction (SPAcatch)
SPFshoulder2 = 834	; 4 frames: hip checks: +0 / +2 left (SPAhipchkl), +1 / +3 right
SPFcelebrate = 838	; 16 frames: celebrating a goal, 2 a direction (SPAcelebrate)
SPFgskate    = 854	; 32 frames: the goalie skating, 4 a direction (SPAgskate; SPAgpoke,
SPFgbutterfly= 886	; 2 frames: the goalie's butterfly (SPAgbutterfly, SPAgcover)
SPFboardfront= 888	; 16 frames: checked into the boards, from the front (SPAboardfront)
SPFboardright= 904	; 16 frames: checked into the boards, from the right (SPAboardright)
SPFboardback = 920	; 14 frames: checked into the boards, from behind (SPAboardback)
SPFboardleft = 934	; 14 frames: checked into the boards, from the left (SPAboardleft)
SPFinjury1   = 948	; 6 frames: lying injured, 3 for each of two sides (SPAinjury1)
SPFgready    = 954	; 18 frames: the goalie ready (SPAgready)
SPFpump2     = 1004	; 16 frames: a stick pump, 2 a direction (SPApump2)
SPFbenchcheck= 1051	; 9 frames: checked into the bench (SPAbenchcheckr)

